import { arbitrumSepolia, arbitrum, hardhat } from "wagmi/chains";

import { DEFAULT_CHAIN } from "consts/chains";

export const getGraphqlUrl = (isDisputeTemplate = false, chainId: number = DEFAULT_CHAIN.id) => {
  const CHAINID_TO_DISPUTE_TEMPLATE_SUBGRAPH = {
    [arbitrumSepolia.id]:
      import.meta.env.REACT_APP_DRT_ARBSEPOLIA_SUBGRAPH ??
      "Environment variable REACT_APP_DRT_ARBSEPOLIA_SUBGRAPH not set.",
    [arbitrum.id]:
      import.meta.env.REACT_APP_DRT_ARBMAINNET_SUBGRAPH ??
      "Environment variable REACT_APP_DRT_ARBMAINNET_SUBGRAPH not set.",
    [hardhat.id]:
      import.meta.env.REACT_APP_DRT_LOCAL_SUBGRAPH ?? "Environment variable REACT_APP_DRT_LOCAL_SUBGRAPH not set.",
  };
  const coreUrl = import.meta.env.REACT_APP_CORE_SUBGRAPH ?? "Environment variables REACT_APP_CORE_SUBGRAPH not set.";
  return isDisputeTemplate
    ? CHAINID_TO_DISPUTE_TEMPLATE_SUBGRAPH[chainId as keyof typeof CHAINID_TO_DISPUTE_TEMPLATE_SUBGRAPH]
    : coreUrl;
};
import React, { useMemo, createContext, useContext } from "react";

import { createBatchingExecutor } from "@graphql-tools/batch-execute";
import { AsyncExecutor, ExecutionResult } from "@graphql-tools/utils";
import { TypedDocumentNode } from "@graphql-typed-document-node/core";
import { create, windowedFiniteBatchScheduler, Batcher } from "@yornaath/batshit";
import { request } from "graphql-request";

import { debounceErrorToast } from "utils/debounceErrorToast";
import { getGraphqlUrl } from "utils/getGraphqlUrl";
interface IGraphqlBatcher {
  graphqlBatcher: Batcher<any, IQuery>;
}

interface IQuery {
  id: string;
  document: TypedDocumentNode<any, any>;
  variables: Record<string, any>;
  isDisputeTemplate?: boolean;
  chainId?: number;
}

const Context = createContext<IGraphqlBatcher | undefined>(undefined);

const fetch = async <TArgs,>(url: string, document: TypedDocumentNode<unknown, TArgs>, variables?: TArgs) => {
  try {
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    //@ts-ignore
    const result = request(url, document, variables).then((res) => ({
      data: res,
    })) as Promise<ExecutionResult>;

    return result;
  } catch (error) {
    console.error("Graph error: ", { error });
    debounceErrorToast("Graph query error: failed to fetch data.");
    return { data: {} };
  }
};

const coreExecutor: AsyncExecutor = async ({ document, variables }) => {
  return fetch(getGraphqlUrl(false), document, variables);
};

const dtrExecutor: AsyncExecutor = async ({ document, variables }) => {
  return fetch(getGraphqlUrl(true), document, variables);
};

const coreBatchExec = createBatchingExecutor(coreExecutor);
const dtrBatchExec = createBatchingExecutor(dtrExecutor);

const fetcher = async (queries: IQuery[]) => {
  const batchdata = await Promise.all(
    queries.map(({ document, variables, isDisputeTemplate }) =>
      isDisputeTemplate
        ? dtrBatchExec({
            document,
            variables,
          })
        : coreBatchExec({
            document,
            variables,
          })
    )
  );

  // eslint-disable-next-line @typescript-eslint/ban-ts-comment
  //@ts-ignore
  const processedData = batchdata.map((data, index) => ({ id: queries[index].id, result: data.data }));
  return processedData;
};

const GraphqlBatcherProvider: React.FC<{ children?: React.ReactNode }> = ({ children }) => {
  const graphqlBatcher = create({
    fetcher,
    resolver: (results, query) => results.find((result) => result.id === query.id)!["result"],
    scheduler: windowedFiniteBatchScheduler({
      windowMs: 100,
      maxBatchSize: 5,
    }),
  });
  return <Context.Provider value={useMemo(() => ({ graphqlBatcher }), [graphqlBatcher])}>{children}</Context.Provider>;
};

export const useGraphqlBatcher = () => {
  const context = useContext(Context);
  if (!context) {
    throw new Error("Context Provider not found.");
  }
  return context;
};

export default GraphqlBatcherProvider;
import React from "react";

import { QueryClient, QueryClientProvider as _QueryClientProvider } from "@tanstack/react-query";

const queryClient = new QueryClient();

const QueryClientProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <_QueryClientProvider client={queryClient}>{children}</_QueryClientProvider>
);

export default QueryClientProvider;
import { ArbitratorTypes, getArbitratorType as _getArbitratorType } from "consts/arbitratorTypes";

import { version, gitCommitHash, gitCommitShortHash, gitBranch, gitTags, clean } from "../generatedGitInfo.json";

export { ArbitratorTypes };

export const ONE_BASIS_POINT = 10000n;

export const REFETCH_INTERVAL = 5000;
export const STALE_TIME = 1000;

export const IPFS_GATEWAY = import.meta.env.REACT_APP_IPFS_GATEWAY || "https://cdn.kleros.link";
export const HERMES_TELEGRAM_BOT_URL =
  import.meta.env.REACT_APP_HERMES_TELEGRAM_BOT_URL || "https://t.me/HermesTheKlerosV2MessengerBot";
export const KLEROS_SCOUT_URL = import.meta.env.REACT_APP_KLEROS_SCOUT_URL || "https://scout-app.kleros.io";

export const GIT_BRANCH = gitBranch;
export const GIT_TAGS = gitTags;
export const GIT_HASH = gitCommitShortHash;
export const GIT_DIRTY = clean ? "" : "-dirty";
export const GIT_URL = `https://github.com/kleros/kleros-v2/tree/${gitCommitHash}/web`;
export const RELEASE_VERSION = version;

// https://www.w3.org/TR/2012/WD-html-markup-20120329/input.email.html#input.email.attrs.value.single

export const EMAIL_REGEX =
  // eslint-disable-next-line max-len
  /^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/;
export const TELEGRAM_REGEX = /^@\w{5,32}$/;
export const ETH_ADDRESS_REGEX = /^0x[a-fA-F0-9]{40}$/;
export const ETH_SIGNATURE_REGEX = /^0x[a-fA-F0-9]{130}$/;

export const isProductionDeployment = () => import.meta.env.REACT_APP_DEPLOYMENT === "mainnet";
export const isTestnetDeployment = () => import.meta.env.REACT_APP_DEPLOYMENT === "testnet";
export const isLocalDeployment = () => import.meta.env.REACT_APP_DEPLOYMENT === "localhost";

export const getArbitratorType = (): ArbitratorTypes =>
  _getArbitratorType(import.meta.env.REACT_APP_ARBITRATOR_TYPE?.toLowerCase());

export const getDevToolsUrl = () => import.meta.env.REACT_APP_DEVTOOLS_URL || "https://devtools.v2.kleros.builders";

export const spamEvidencesIds: string[] = (import.meta.env.REACT_APP_SPAM_EVIDENCES_IDS ?? "").split(",");

export const HARDHAT_NODE_RPC = "http://127.0.0.1:8545";
import { arbitrum, arbitrumSepolia } from "viem/chains";

import { ArbitratorTypes } from "consts/arbitratorTypes";

export { ArbitratorTypes };

export const ONE_BASIS_POINT = 10000n;

export const REFETCH_INTERVAL = 5000;

export const IPFS_GATEWAY = process.env.REACT_APP_IPFS_GATEWAY || "https://cdn.kleros.link";
export const HERMES_TELEGRAM_BOT_URL =
  process.env.REACT_APP_HERMES_TELEGRAM_BOT_URL || "https://t.me/HermesTheKlerosV2MessengerBot";

// https://www.w3.org/TR/2012/WD-html-markup-20120329/input.email.html#input.email.attrs.value.single

export const EMAIL_REGEX = /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9-]+(?:\.[a-zA-Z0-9-]+)*$/;
export const TELEGRAM_REGEX = /^@\w{5,32}$/;
export const ETH_ADDRESS_REGEX = /^0x[a-fA-F0-9]{40}$/;
export const ETH_SIGNATURE_REGEX = /^0x([a-fA-F0-9]{130})+$|^0x$/;

export const isProductionDeployment = () => process.env.REACT_APP_DEPLOYMENT === "mainnet";
export const isLocalDeployment = () => process.env.REACT_APP_DEPLOYMENT === "localhost";

export const INVALID_DISPUTE_DATA_ERROR = `The dispute data is not valid, please vote "Refuse to arbitrate"`;
export const RPC_ERROR = `RPC Error: Unable to fetch dispute data. Please avoid voting.`;

