import { useEffect, useState } from "react";

import { UseQueryResult } from "@tanstack/react-query";

import { useHomePageBlockQuery, HomePageBlockStats } from "./useHomePageBlockQuery";

type ReturnType = UseQueryResult<HomePageBlockStats, Error>;

export const useHomePageExtraStats = (days: number | string): ReturnType => {
  const [pastTimestamp, setPastTimestamp] = useState<bigint | undefined>();

  useEffect(() => {
    if (typeof days !== "string") {
      const currentTimestamp = BigInt(Math.floor(Date.now() / 1000)); // Current time in seconds
      const secondsInDays = BigInt(days * 24 * 3600);
      const pastTime = currentTimestamp - secondsInDays;
      setPastTimestamp(pastTime);
    }
  }, [days]);

  const data = useHomePageBlockQuery(pastTimestamp, days === "allTime");
  return data;
};
import { useQuery } from "@tanstack/react-query";
import { getContract } from "viem";
import { usePublicClient } from "wagmi";

import { DEFAULT_CHAIN } from "consts/chains";
import { policyRegistryConfig } from "hooks/contracts/generated";
import { isUndefined } from "utils/index";

export const usePolicyRegistryEvent = (courtID?: string | number) => {
  const publicClient = usePublicClient();
  const isEnabled = !isUndefined(publicClient) && !isUndefined(courtID);

  return useQuery({
    queryKey: [`PolicyRegistry${courtID}`],
    enabled: isEnabled,
    staleTime: Infinity,
    queryFn: async () => {
      if (isUndefined(publicClient) || isUndefined(courtID)) throw new Error("publicClient or courtID is undefined");
      const chainKey = DEFAULT_CHAIN.id;
      const policyRegistry = getContract({
        abi: policyRegistryConfig.abi,
        address: policyRegistryConfig.address[chainKey],
        client: { public: publicClient },
      });
      const policyFilter = await policyRegistry.createEventFilter.PolicyUpdate({
        _courtID: BigInt(courtID),
      });
      const policyUpdateEvents = await publicClient.getFilterLogs({
        filter: policyFilter,
      });
      return policyUpdateEvents[0];
    },
  });
};
import { useQuery } from "@tanstack/react-query";
import { Address, getContract } from "viem";
import { usePublicClient } from "wagmi";

import { isUndefined } from "utils/index";

import { getDisputeKitConfigByAddress } from "src/dispute-kits";

export const useDisputeKitMultipliers = (disputeKitAddress?: Address) => {
  const publicClient = usePublicClient();
  const isEnabled = !isUndefined(publicClient) && !isUndefined(disputeKitAddress);

  return useQuery({
    queryKey: [`DisputeKitMultipliers`, disputeKitAddress],
    enabled: isEnabled,
    staleTime: Infinity,
    queryFn: async () => {
      if (!publicClient || !disputeKitAddress) return;
      const config = getDisputeKitConfigByAddress(disputeKitAddress);
      if (isUndefined(config)) return;

      const disputeKit = getContract({
        abi: config.disputeKitAbi,
        address: config.address,
        client: {
          public: publicClient,
        },
      });
      const winner_stake_multiplier = await disputeKit.read.WINNER_STAKE_MULTIPLIER();
      const loser_stake_multiplier = await disputeKit.read.LOSER_STAKE_MULTIPLIER();
      const loser_appeal_period_multiplier = await disputeKit.read.LOSER_APPEAL_PERIOD_MULTIPLIER();
      return {
        winner_stake_multiplier,
        loser_stake_multiplier,
        loser_appeal_period_multiplier,
      };
    },
  });
};

