import type { Address, Chain, WalletClient } from "viem";

export interface CommitContext {
  /** Account of Juror */
  account: Address;
  chain: Chain;
  walletClient: WalletClient;
}
import { DisputeKits } from "src/dispute-kits/disputeKits";

interface BaseCommitParams {
  disputeId: bigint;
  voteIds: bigint[];
  choice: bigint;
  salt: bigint;
  roundIndex: number;
  disputeKitId: DisputeKits;
}

export interface ClassicCommitParams extends BaseCommitParams {
  disputeKitId: DisputeKits.Classic;
}

export interface ShutterCommitParams extends BaseCommitParams {
  disputeKitId: DisputeKits.Shutter;
  decryptionDelay: number;
  justification: string;
}

export interface GatedCommitParams extends BaseCommitParams {
  disputeKitId: DisputeKits.Gated;
}

export interface GatedShutterCommitParams extends BaseCommitParams {
  disputeKitId: DisputeKits.GatedShutter;
  decryptionDelay: number;
  justification: string;
}

export interface ArgentinaConsumerProtectionCommitParams extends BaseCommitParams {
  disputeKitId: DisputeKits.ArgentinaConsumerProtection;
}

export interface ClassicUniversityCommitParams extends BaseCommitParams {
  disputeKitId: DisputeKits.ClassicUniversity;
}

export type CommitParams =
  | ClassicCommitParams
  | ShutterCommitParams
  | GatedCommitParams
  | GatedShutterCommitParams
  | ArgentinaConsumerProtectionCommitParams
  | ClassicUniversityCommitParams;
import { encrypt } from "utils/crypto/shutter";

import { storeCommitData } from "../helpers/storage";

/**
 * Provides dependencies for commit builders.
 *
 * This interface enables dependency injection so implementations can be
 * customized or replaced if needed.
 *
 * @remarks
 * Builder-specific dependencies should extend this interface rather than modifying it.
 */
interface BaseCommitBuilderDeps {
  storeCommitData: typeof storeCommitData;
}

// eslint-disable-next-line @typescript-eslint/no-empty-object-type
export interface ClassicCommitDeps extends BaseCommitBuilderDeps {}

export interface ShutterCommitDeps extends BaseCommitBuilderDeps {
  encrypt: typeof encrypt;
}

// eslint-disable-next-line @typescript-eslint/no-empty-object-type
export interface GatedCommitDeps extends BaseCommitBuilderDeps {}

export interface GatedShutterCommitDeps extends BaseCommitBuilderDeps {
  encrypt: typeof encrypt;
}

// eslint-disable-next-line @typescript-eslint/no-empty-object-type
export interface ArgentinaConsumerProtectionCommitDeps extends BaseCommitBuilderDeps {}

// eslint-disable-next-line @typescript-eslint/no-empty-object-type
export interface ClassicUniversityCommitDeps extends BaseCommitBuilderDeps {}

export type CommitBuilderDeps =
  | ClassicCommitDeps
  | ShutterCommitDeps
  | GatedCommitDeps
  | GatedShutterCommitDeps
  | ArgentinaConsumerProtectionCommitDeps
  | ClassicUniversityCommitDeps;

export const defaultCommitBuilderDeps: BaseCommitBuilderDeps = {
  storeCommitData,
};
import { buildCommitTxn } from "./builders";
import type { CommitContext } from "./context";
import type { CommitParams } from "./params";

/**
 * Builds a commit transaction and sends it to the relevant DisputeKit contract.
 *
 * @param params  Parameters for the commit transaction. Must include a `disputeKitId` field
 *                corresponding to a `DisputeKits` value.
 * @param context Execution context, usually including chain info, account data,
 *                and a `walletClient` to send the transaction.
 *
 * @returns The transaction hash.
 *
 * @dev Internally, this calls {@link buildCommitTxn} to construct the transaction
 * (ABI, functionName, args, etc.) and then executes it via the `walletClient`
 * provided in `context`.
 */
export async function executeCommit(params: CommitParams, context: CommitContext) {
  const tx = await buildCommitTxn(params, context);
  const { walletClient } = context;
  return walletClient.writeContract(tx);
}
import { DisputeKits } from "src/dispute-kits";

import { CommitContext } from "../context";
import { CommitParams } from "../params";

import { argentinaConsumerProtectionCommitBuilder } from "./argentinaConsumerProtection.builder";
import { CommitBuilder } from "./baseBuilder";
import { classicCommitBuilder } from "./classic.builder";
import { classicUniversityCommitBuilder } from "./classicUniversity.builder";
import { gatedCommitBuilder } from "./gated.builder";
import { gatedShutterCommitBuilder } from "./gatedShutter.builder";
import { shutterCommitBuilder } from "./shutter.builder";

/**
 * Mapping of dispute kit types to their respective commit builders.
 *
 * Each builder handles the construction of a transaction for the
 * specific dispute kit, including preparing ABI, functionName,
 * args.
 */
const builders: Record<DisputeKits, CommitBuilder> = {
  [DisputeKits.Classic]: classicCommitBuilder,
  [DisputeKits.Shutter]: shutterCommitBuilder,
  [DisputeKits.Gated]: gatedCommitBuilder,
  [DisputeKits.GatedShutter]: gatedShutterCommitBuilder,
  [DisputeKits.ArgentinaConsumerProtection]: argentinaConsumerProtectionCommitBuilder,
  [DisputeKits.ClassicUniversity]: classicUniversityCommitBuilder,
};

/**
 * Builds a commit transaction for a given dispute kit type.
 *
 * This function selects the correct commit builder based on
 * `params.disputeKitId` and calls its `build` method, passing the
 * caller-provided `params` and `context`. Dependencies are
 * automatically resolved via each builder's defaults.
 *
 * @param params  Parameters for the commit transaction. Must include
 *                a `disputeKitId` field corresponding to a `DisputeKits` value.
 * @param context Execution context, usually including chain info and
 *                account data required by the builder.
 *
 * @returns Returns transaction parameters (ABI, functionName, args, etc.) for call to the relevant DisputeKit
 */
export const buildCommitTxn = (params: CommitParams, context: CommitContext) => {
  return builders[params.disputeKitId].build(params, context);
};
import { defineActionBuilder } from "actions/helpers/builder";

import { CommitContext } from "../context";
import { CommitBuilderDeps, defaultCommitBuilderDeps } from "../deps";
import { CommitParams } from "../params";

/**
 * Typed factory for Commit action builders.
 *
 * This binds the generic {@link defineActionBuilder} helper to:
 * - {@link CommitParams}   – parameters supplied by the caller (UI / app logic)
 * - {@link CommitContext}  – execution context (account, chain, wallet client)
 * - {@link CommitBuilderDeps} – full dependency set required by commit builders
 *
 * {@link defaultCommitBuilderDeps} are provided here as the **global default
 * dependencies** for all commit builders. These typically include shared
 * dependencies such as storage helpers or crypto utilities.
 *
 * Individual commit builders may:
 * - Declare additional builder-specific defaults via `builderDeps`
 *   (e.g. shutter specific encryption helpers)
 * - Override any default dependency if required
 *
 * Callers (including tests) may further override dependencies at build time
 * by passing a partial dependency object to `builder.build(...)`.
 *
 * Dependency resolution order (last one takes precedence):
 * 1. Global defaults defined here
 * 2. Builder-level defaults (`builder.builderDeps`)
 * 3. Call-site overrides passed to `build(...)`
 */
export const defineCommitBuilder = defineActionBuilder<CommitParams, CommitContext, CommitBuilderDeps>(
  defaultCommitBuilderDeps
);

/**
 * Concrete CommitBuilder type produced by {@link defineCommitBuilder}.
 *
 * Each commit builder exposes a `build(params, context, deps?)` function
 * that returns a fully-typed transaction object ready to be submitted via
 * a wallet client.
 */
export type CommitBuilder = ReturnType<typeof defineCommitBuilder>;
import { Hex } from "viem";

import { getVoteKey } from "actions/helpers/storage/getVoteKey";

import { disputeKitShutterAbi, disputeKitShutterAddress } from "hooks/contracts/generated";
import { hashJustification } from "utils/crypto/hashJustification";
import { hashVote } from "utils/crypto/hashVote";
import { encrypt } from "utils/crypto/shutter";

import { ShutterCommitDeps } from "../deps";
import { encodeShutterMessage } from "../helpers";
import { ShutterCommitParams } from "../params";

import { defineCommitBuilder } from "./baseBuilder";

export const shutterCommitBuilder = defineCommitBuilder({
  builderDeps: {
    encrypt,
  },
  build: async (params: ShutterCommitParams, context, deps: ShutterCommitDeps) => {
    if (!import.meta.env.REACT_APP_SHUTTER_API || import.meta.env.REACT_APP_SHUTTER_API.trim() === "") {
      console.error("REACT_APP_SHUTTER_API environment variable is not set or is empty");
      throw new Error("Cannot commit vote: REACT_APP_SHUTTER_API environment variable is required but not set");
    }

    const { disputeId, voteIds, choice, salt, decryptionDelay, justification, roundIndex } = params;
    const { chain, account } = context;

    const key = getVoteKey(disputeId, roundIndex, voteIds);
    deps.storeCommitData(key, { choice, salt, justification });

    const encodedMessage = encodeShutterMessage(choice, salt, justification);

    const { encryptedCommitment, identity } = await deps.encrypt(encodedMessage, decryptionDelay);

    const choiceCommit = hashVote(choice, BigInt(salt));
    const justificationCommit = hashJustification(BigInt(salt), justification);
    const chainKey = chain.id as keyof typeof disputeKitShutterAddress;

    return {
      account,
      address: disputeKitShutterAddress[chainKey],
      abi: disputeKitShutterAbi,
      functionName: "castCommitShutter",
      args: [disputeId, voteIds, choiceCommit, justificationCommit, identity as Hex, encryptedCommitment],
      chain,
    };
  },
});
const SEPARATOR = "-";
export const encodeShutterMessage = (choice: bigint, salt: bigint, justification: string) => {
  return `${choice.toString()}${SEPARATOR}${salt.toString()}${SEPARATOR}${justification}`;
};

