import { toast, ToastPosition, Theme } from "react-toastify";
import { PublicClient, TransactionReceipt } from "viem";

import { parseWagmiError } from "./parseWagmiError";

export const OPTIONS = {
  position: "top-center" as ToastPosition,
  autoClose: 5000,
  hideProgressBar: false,
  closeOnClick: true,
  pauseOnHover: true,
  draggable: true,
  progress: undefined,
  theme: "colored" as Theme,
};

type WrapWithToastReturnType = {
  status: boolean;
  result?: TransactionReceipt;
};

export const infoToast = (message: string) => toast.info(message, OPTIONS);
export const successToast = (message: string) => toast.success(message, OPTIONS);
export const errorToast = (message: string) => toast.error(message, OPTIONS);

export async function wrapWithToast(
  contractWrite: () => Promise<`0x${string}`>,
  publicClient: PublicClient
): Promise<WrapWithToastReturnType> {
  toast.info("Transaction initiated", OPTIONS);
  return await contractWrite()
    .then(
      async (hash) =>
        await publicClient.waitForTransactionReceipt({ hash, confirmations: 2 }).then((res: TransactionReceipt) => {
          const status = res.status === "success";

          if (status) toast.success("Transaction mined!", OPTIONS);
          else toast.error("Transaction reverted!", OPTIONS);

          return { status, result: res };
        })
    )
    .catch((error) => {
      toast.error(parseWagmiError(error), OPTIONS);
      return { status: false };
    });
}

export async function catchShortMessage(promise: Promise<any>) {
  return await promise.catch((error) => toast.error(parseWagmiError(error), OPTIONS));
}
import { useCallback } from "react";

import { encodeFunctionData, type SimulateContractParameters } from "viem";

import { isUndefined } from "src/utils";

import { useSimulateTransactionBatcherBatchSend, useWriteTransactionBatcherBatchSend } from "./contracts/generated";

export type TransactionBatcherConfig = SimulateContractParameters[];

type TransactionBatcherOptions = {
  // determines if simulation query is enabled
  enabled: boolean;
};

/**
 * @param configs SimulateContractParameters[] - an array of useWriteContract Parameters
 * @param options TransactionBatcherOptions - an object containing options to apply to hook behaviour
 * @description This takes in multiple write calls and batches them into a single transaction
 * @example useTransactionBatcher([
 *                 { address : "contract one address",
 *                   abi : "contract one abi",
 *                   functionName : "...",
 *                   args: [...]
 *                   value: 0
 *                 },
 *                 { address : "contract 2 address",
 *                   abi : "contract 2 abi",
 *                   functionName : "...",
 *                   args: [...]
 *                   value: 0
 *                 },
 *                ])
 */
const useTransactionBatcher = (
  configs?: TransactionBatcherConfig,
  options: TransactionBatcherOptions = { enabled: true }
) => {
  const validatedConfigs = configs ?? [];
  const totalValue = validatedConfigs.reduce((sum, config) => {
    return sum + (config?.value ?? BigInt(0));
  }, BigInt(0));

  const {
    data: batchConfig,
    isLoading,
    isError,
    error,
  } = useSimulateTransactionBatcherBatchSend({
    query: {
      enabled: !isUndefined(configs) && options.enabled,
    },
    args: [
      validatedConfigs.map((config) => config?.address),
      validatedConfigs.map((config) => config?.value ?? BigInt(0)),
      validatedConfigs.map((config) => encodeFunctionData(config)),
    ],
    value: totalValue,
  });
  const { writeContractAsync } = useWriteTransactionBatcherBatchSend();

  const executeBatch = useCallback(
    (config: NonNullable<typeof batchConfig>) => writeContractAsync(config?.request),
    [writeContractAsync]
  );

  return { executeBatch, batchConfig, isError, isLoading, error };
};

export default useTransactionBatcher;
import { type UseSimulateContractReturnType } from "wagmi";

type ExtendedWagmiError = UseSimulateContractReturnType["error"] & { shortMessage?: string; metaMessages?: string[] };

/**
 * @param error
 * @description Tries to extract the human readable error message, otherwise reverts to error.message
 * @returns Human readable error if possible
 */
export const parseWagmiError = (error: UseSimulateContractReturnType["error"]) => {
  if (!error) return "";
  const extError = error as ExtendedWagmiError;

  const metaMessage = extError?.metaMessages?.[0];
  const shortMessage = extError?.shortMessage;

  return metaMessage ?? shortMessage ?? error.message;
};
import { toast } from "react-toastify";

import { OPTIONS as toastOptions } from "utils/wrapWithToast";

let timeoutId: NodeJS.Timeout;
export const debounceErrorToast = (msg: string) => {
  if (timeoutId) clearTimeout(timeoutId);

  timeoutId = setTimeout(() => {
    toast.error(msg, toastOptions);
  }, 5000);
};
export async function refetchWithRetry<T>(fn: () => Promise<T>, retryCount = 5, retryDelay = 2000) {
  let attempts = 0;

  while (attempts < retryCount) {
    try {
      const returnData = await fn();

      //@ts-expect-error data does exist
      if (returnData && returnData?.data !== undefined) {
        return returnData;
      }
    } catch (error) {
      console.error(`Attempt ${attempts + 1} failed with error:`, error);
    }

    attempts++;

    if (attempts >= retryCount) {
      return;
    }

    await new Promise((resolve) => setTimeout(resolve, retryDelay));
  }
  return;
}
import { useLocalStorage } from "react-use";
import { Hex, WalletClient, keccak256 } from "viem";
import { privateKeyToAccount } from "viem/accounts";
import { useWalletClient } from "wagmi";

import messages from "consts/eip712-messages";
import { isUndefined } from "utils/index";

const useSigningAccount = () => {
  const { data: wallet } = useWalletClient();
  const address = wallet?.account.address;
  const key = `signingAccount-${address}`;
  const [signingKey, setSigningKey] = useLocalStorage<Hex>(key);
  return {
    signingAccount: !isUndefined(signingKey) ? privateKeyToAccount(signingKey) : undefined,
    generateSigningAccount: () => (!isUndefined(wallet) ? generateSigningAccount(wallet, setSigningKey) : undefined),
  };
};

const generateSigningAccount = async (wallet: WalletClient, setSigningKey: (signingKey: `0x${string}`) => void) => {
  if (isUndefined(wallet.account)) return;
  const signature = await wallet.signTypedData(messages.signingAccount(wallet.account.address));
  const signingKey = keccak256(signature);
  setSigningKey(signingKey);
  return privateKeyToAccount(signingKey);
};

export default useSigningAccount;
