    functionName: "maxDrawingTime",
    query: { refetchInterval: REFETCH_INTERVAL },
  });
};

export const useReadSortitionModuleMinStakingTime = () => {
  return useReadSortitionModule({
    // eslint-disable-next-line
    // @ts-ignore
    functionName: "minStakingTime",
    query: { refetchInterval: REFETCH_INTERVAL },
  });
};
import { useQuery } from "@tanstack/react-query";

import { getIpfsUrl } from "utils/getIpfsUrl";
import { isUndefined } from "utils/index";

export const useIPFSQuery = (ipfsPath?: string) => {
  const isEnabled = !isUndefined(ipfsPath);
  return useQuery({
    queryKey: [`IPFS${ipfsPath}`],
    enabled: isEnabled,
    staleTime: Infinity,
    queryFn: async () => {
      if (isEnabled) {
        return fetch(getIpfsUrl(ipfsPath)).then(async (res) => await res.json());
      }
      return undefined;
    },
  });
};
import { IPFS_GATEWAY } from "consts/index";

export const getIpfsUrl = (url: string) => {
  const formatedIPFSPath = getFormattedPath(url);
  return `${IPFS_GATEWAY}${formatedIPFSPath}`;
};

export const getFormattedPath = (url: string) => {
  if (url.startsWith("/ipfs/")) return url;
  else if (url.startsWith("ipfs/")) return "/" + url;
  else if (url.startsWith("ipfs://")) return url.replace("ipfs://", "/ipfs/");
  return url;
};
import { useLocation } from "react-router-dom";

import { Dispute_Filter } from "src/graphql/graphql";

export const encodeURIFilter = (filter: Dispute_Filter): string => {
  if (Object.keys(filter).length === 0) {
    return "all";
  }
  return encodeURIComponent(JSON.stringify(filter));
};

export const decodeURIFilter = (filter: string): Dispute_Filter => {
  if (filter === "all") {
    return {};
  }
  return JSON.parse(decodeURI(filter));
};

export const useRootPath = () => {
  const location = useLocation();
  return location.pathname.split("/").slice(0, -3).join("/");
};

