import { Address, Hash } from "viem";

import { Roles } from "@kleros/kleros-app";

import { DEFAULT_CHAIN } from "consts/chains";

export const isUndefined = (maybeObject: any): maybeObject is undefined | null =>
  typeof maybeObject === "undefined" || maybeObject === null;

/**
 * Checks if a string is empty or contains only whitespace.
 */
export const isEmpty = (str: string): boolean => str.trim() === "";

export const getTxnExplorerLink = (hash: Hash) => `${DEFAULT_CHAIN?.blockExplorers?.default.url}/tx/${hash}`;

export const getAddressExplorerLink = (address: Address) =>
  `${DEFAULT_CHAIN?.blockExplorers?.default.url}/address/${address}`;

type Role = {
  name: string;
  restriction: {
    maxSize: number;
    allowedMimeTypes: string[];
  };
};

export const getFileUploaderMsg = (
  role: Roles,
  roleRestrictions?: Role[],
  t?: (key: string, params?: any) => string
) => {
  if (!roleRestrictions) return;
  const restrictions = roleRestrictions.find(
    (supportedRoles) => Roles[supportedRoles.name as keyof typeof Roles] === role
  );

  if (!restrictions) return;
  const typesString = restrictions.restriction.allowedMimeTypes
    .map((type) => {
      const [prefix, suffix] = type.split("/");
      if (!suffix) return prefix ?? null;

      return suffix === "*" ? prefix : suffix;
    })
    .join(", ");

  const maxSizeMB = (restrictions.restriction.maxSize / (1024 * 1024)).toFixed(2);

  if (t) {
    return t("forms.messages.allowed_file_types", { types: typesString, maxSize: maxSizeMB });
  }

  return `Allowed file types: [${typesString}], Max allowed size: ${maxSizeMB} MB.`;
};
export function commify(value: string | number): string {
  const comps = String(value).split(".");

  if (!String(value).match(/^-?\d+(\.\d+)?$/)) {
    return "0";
  }

  // Make sure we have at least one whole digit (0 if none)
  let whole = comps[0];

  let negative = "";
  if (whole.substring(0, 1) === "-") {
    negative = "-";
    whole = whole.substring(1);
  }

  // Make sure we have at least 1 whole digit with no leading zeros
  while (whole.substring(0, 1) === "0") {
    whole = whole.substring(1);
  }
  if (whole === "") {
    whole = "0";
  }

  let suffix = "";
  if (comps.length === 2) {
    suffix = "." + (comps[1] || "0");
  }
  while (suffix.length > 2 && suffix[suffix.length - 1] === "0") {
    suffix = suffix.substring(0, suffix.length - 1);
  }

  const formatted: string[] = [];
  while (whole.length) {
    if (whole.length <= 3) {
      formatted.unshift(whole);
      break;
    } else {
      const index = whole.length - 3;
      formatted.unshift(whole.substring(index));
      whole = whole.substring(0, index);
    }
  }

  if (suffix === ".0") suffix = "";

  return negative + formatted.join(",") + suffix;
}

export function uncommify(value: string): string {
  return value.replace(/,/g, "");
}
import { formatEther, formatUnits } from "viem";

import { commify } from "./commify";

export const roundNumberDown = (value: number, fractionDigits = 0) => {
  const factor = 10 ** fractionDigits;
  return Math.floor(value * factor) / factor;
};

export const formatUnitsWei = (value: bigint) => formatUnits(value, 18);

export const formatValue = (value: string, fractionDigits: number, roundDown: boolean) => {
  let units = Number(value);
  if (roundDown) units = roundNumberDown(units, fractionDigits);
  return commify(units.toFixed(fractionDigits));
};

export const formatPNK = (value: bigint, fractionDigits = 0, roundDown = false) =>
  formatValue(formatUnitsWei(value), fractionDigits, roundDown);

export const formatETH = (value: bigint, fractionDigits = 4, roundDown = false) =>
  formatValue(formatEther(value), fractionDigits, roundDown);

export const formatUSD = (value: number, fractionDigits = 2) => "$" + commify(Number(value).toFixed(fractionDigits));
export function getCurrentTime(): number {
  return Math.floor(Date.now() / 1000);
}

export function getTimeLeft(deadline: number): number {
  const currentTime = getCurrentTime();
  return Math.max(deadline - currentTime, 0);
}

export function secondsToDayHourMinute(seconds: number): string {
  const d = Math.floor(seconds / (3600 * 24));
  const h = Math.floor((seconds % (3600 * 24)) / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = seconds % 60;
  return d > 0 ? `${d}d ${h}h ${m}m` : `${h}h ${m}m ${s}s`;
}

export function getOneYearAgoTimestamp(): number {
  const currentTime = new Date().getTime() / 1000;
  return currentTime - 31536000; // One year in seconds
}

export function formatDate(unixTimestamp: number, withTime = false, locale = "en-US"): string {
  const date = new Date(unixTimestamp * 1000);
  const options: Intl.DateTimeFormatOptions = withTime
    ? {
        month: "short",
        day: "2-digit",
        year: "numeric",
        hour: "numeric",
        minute: "numeric",
        timeZone: "GMT",
        timeZoneName: "short",
      }
    : { month: "long", day: "2-digit", year: "numeric" };
  return date.toLocaleDateString(locale, options);
}

export function formatDateWithTime(timestamp: string): string {
  const date = new Date(parseInt(timestamp) * 1000);
  return date.toLocaleDateString("en-GB", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

/**
 * Calculates the time left until a specified date and formats it.
 *
 * @param {string} isoString - An ISO 8601 formatted date string (e.g., "2024-10-29T09:52:08.580Z").
 * @returns {string} A human-readable string indicating the time left until the specified date.
 * @example
 * console.log(timeLeftUntil("2024-10-29T09:52:08.580Z"));
 * // Outputs: "in x secs", "in x mins", "in x hrs", or "after October 29, 2024"
 */
export function timeLeftUntil(isoString: string): string {
  const targetDate = new Date(isoString);
  const now = new Date();
  const timeDifference = targetDate.getTime() - now.getTime();

  if (timeDifference <= 0) {
    return "The date has already passed.";
  }

  const secondsLeft = Math.floor(timeDifference / 1000);
  const minutesLeft = Math.floor(secondsLeft / 60);
  const hoursLeft = Math.floor(minutesLeft / 60);
  const daysLeft = Math.floor(hoursLeft / 24);

  if (secondsLeft < 60) {
    return `in ${secondsLeft} sec${secondsLeft > 1 ? "s" : ""}`;
  } else if (minutesLeft < 60) {
    return `in ${minutesLeft} min${minutesLeft > 1 ? "s" : ""}`;
  } else if (hoursLeft < 24) {
    return `in ${hoursLeft} hr${hoursLeft > 1 ? "s" : ""}`;
