    return formattedAddress.substring(0, 6) + "..." + formattedAddress.substring(formattedAddress.length - 4);
  } catch {
    throw new TypeError("Invalid input, address can't be parsed");
  }
}
import { CourtTreeQuery } from "src/graphql/graphql";

export const findCourtNameById = (courtTreeData: CourtTreeQuery | undefined, courtId: string) => {
  if (!courtTreeData) return undefined;
  const traverse = (court: CourtTreeQuery["court"]): string | null | undefined => {
    if (!court) return null;
    if (court.id === courtId) return court.name;
    for (const child of court.children) {
      const found = traverse(child as CourtTreeQuery["court"]);
      if (found) return found;
    }
    return null;
  };

  return traverse(courtTreeData.court) ?? undefined;
};
export const getDescriptiveCourtName = (courtName?: string): string => {
  if (!courtName) return "";
  const lc = courtName.toLowerCase();
  return lc.endsWith("court") || lc.startsWith("corte") ? courtName : `${courtName} Court`;
};
import { decodeEventLog, getAbiItem, Log, Address, toEventSelector } from "viem";

import { DEFAULT_CHAIN } from "consts/chains";
import { klerosCoreAbi, klerosCoreAddress } from "hooks/contracts/generated";

/**
 * Extracts the dispute ID from DisputeCreation event emitted by Kleros core.
 *
 * @param logs - Logs array from dispute transaction receipt
 * @param coreAddress - kleros core address (optional)
 * @returns The dispute ID if found, otherwise `undefined`
 * @todo Write unit test
 */
export function retrieveDisputeIdFromLogs(
  logs: readonly Log[],
  coreAddress: Address = klerosCoreAddress[DEFAULT_CHAIN.id]
) {
  const eventAbi = getAbiItem({
    abi: klerosCoreAbi,
    name: "DisputeCreation",
  });

  const disputeCreationEventTopic = toEventSelector(eventAbi);

  const log = logs.find(
    (l) => l.address.toLowerCase() === coreAddress.toLowerCase() && l.topics[0] === disputeCreationEventTopic
  );

  if (!log) return undefined;

  const { args } = decodeEventLog({
    abi: [eventAbi],
    data: log.data,
    topics: log.topics,
  });

  return args._disputeID;
}
import { Hash, createPublicClient, decodeEventLog, getEventSelector, http } from "viem";
import * as chains from "viem/chains";

import { iArbitrableV2Abi } from "hooks/contracts/generated";
import { isUndefined } from "utils/index";

/**
 * Gets the chain object for the given chain id.
 * @param chainId - Chain id of the target EVM chain.
 * @returns Viem's chain object.
 */
const getChain = (chainId: number) => {
  for (const chain of Object.values(chains)) {
    if ("id" in chain) {
      if (chain.id === chainId) {
        return chain;
      }
    }
  }

  throw new Error(`Chain with id ${chainId} not found`);
};

// Warning  : do not import this in any pages except DisputeTemplatePreview, this has a large bundle size.
export const getDisputeRequestParamsFromTxn = async (hash: Hash, chainId: number) => {
  try {
    const publicClient = createPublicClient({
      chain: getChain(chainId),
      transport: http(),
    });

    const txn = await publicClient.getTransactionReceipt({
      hash,
    });

    const selector = getEventSelector("DisputeRequest(address,uint256,uint256,uint256,string)");
    const disputeRequestEvent = txn.logs.find((log) => log.topics[0] === selector);
    if (isUndefined(disputeRequestEvent)) return undefined;

    const topics = decodeEventLog({
      abi: iArbitrableV2Abi,
      eventName: "DisputeRequest",
      topics: disputeRequestEvent?.topics,
      data: disputeRequestEvent?.data,
    });

    return {
      ...topics?.args,
      _arbitrable: disputeRequestEvent.address,
    };
  } catch (e) {
    console.error("Error getting txn :", { e });

    return undefined;
  }
};
