  const currentLocalRoundIndex = lastDisputeKitDispute?.currentLocalRoundIndex;
  if (isUndefined(currentLocalRoundIndex)) return undefined;

  const adjustedRoundIndex = ["appeal", "execution"].includes(period)
    ? Number(BigInt(currentLocalRoundIndex))
    : Number(BigInt(currentLocalRoundIndex) - 1n);

  return getLocalRounds(dispute.disputeKitDispute)[adjustedRoundIndex];
};

const getOptions = (dispute?: DisputeDetails, classicDispute?: ClassicAppealQuery["dispute"]) => {
  if (!dispute || Object.keys(dispute).length === 0) return [];
  const currentLocalRound = getCurrentLocalRound(classicDispute);
  const classicAnswers = currentLocalRound?.answers;

  const options = dispute.answers?.map((answer) => {
    const classicAnswer = classicAnswers?.find((classicAnswer) => BigInt(classicAnswer.answerId) == BigInt(answer.id));
    // converting hexadecimal id to stringified bigint to match id fomr subgraph
    return {
      ...answer,
      id: BigInt(answer.id).toString(),
      paidFee: classicAnswer?.paidFee ?? "0",
      funded: classicAnswer?.funded ?? false,
    };
  });
  return options;
};

const getFundedChoices = (dispute?: ClassicAppealQuery["dispute"]) => {
  const currentLocalRound = getCurrentLocalRound(dispute);
  return currentLocalRound?.fundedChoices;
};

const getWinningChoice = (dispute?: ClassicAppealQuery["dispute"]) => {
  const currentLocalRound = getCurrentLocalRound(dispute);
  return currentLocalRound?.winningChoice;
};

export const getRequiredFunding = (appealCost = 0n, stake_multiplier = 0n): bigint =>
  appealCost + (stake_multiplier * appealCost) / ONE_BASIS_POINT;

function useLoserSideCountdown(lastPeriodChange = "0", appealPeriodDuration = "0", loserTimeMultiplier = "0") {
  const deadline = useMemo(
    () => getDeadline(lastPeriodChange, appealPeriodDuration, loserTimeMultiplier),
    [lastPeriodChange, appealPeriodDuration, loserTimeMultiplier]
  );
  return useCountdown(deadline);
}

function useWinnerSideCountdown(lastPeriodChange = "0", appealPeriodDuration = "0") {
  const deadline = useMemo(
    () => Number(BigInt(lastPeriodChange) + BigInt(appealPeriodDuration)),
    [lastPeriodChange, appealPeriodDuration]
  );
  return useCountdown(deadline);
}

const getDeadline = (lastPeriodChange: string, appealPeriodDuration: string, loserTimeMultiplier: string): number => {
  const parsedLastPeriodChange = BigInt(lastPeriodChange);
  const parsedAppealPeriodDuration = BigInt(appealPeriodDuration);
  const parsedLoserTimeMultiplier = BigInt(loserTimeMultiplier);
  const loserAppealPeriodDuration = (parsedAppealPeriodDuration * parsedLoserTimeMultiplier) / ONE_BASIS_POINT;
  return Number(loserAppealPeriodDuration + parsedLastPeriodChange);
};
const NewDisputeContext = createContext<INewDisputeContext | undefined>(undefined);

export const useNewDisputeContext = () => {
  const context = useContext(NewDisputeContext);
  if (!context) {
    throw new Error("Context Provider not found.");
  }
  return context;
};

export const NewDisputeProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [disputeData, setDisputeData] = useLocalStorage<IDisputeData>("disputeData", initialDisputeData);
  const [isSubmittingCase, setIsSubmittingCase] = useState<boolean>(false);
  const [isPolicyUploading, setIsPolicyUploading] = useState<boolean>(false);
  const [isBatchCreation, setIsBatchCreation] = useState<boolean>(false);
  const [batchSize, setBatchSize] = useLocalStorage<number>("disputeBatchSize", MIN_DISPUTE_BATCH_SIZE);
  const [selectedFeatures, setSelectedFeatures] = useState<Features[]>([]);

  const disputeTemplate = useMemo(() => constructDisputeTemplate(disputeData), [disputeData]);
  const location = useLocation();

  const resetDisputeData = useCallback(() => {
    const freshData = getInitialDisputeData();
    setDisputeData(freshData);
    setBatchSize(MIN_DISPUTE_BATCH_SIZE);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    // Cleanup function to clear local storage when user leaves the route
    if (location.pathname.includes("/resolver") || location.pathname.includes("/attachment")) return;

    resetDisputeData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [location.pathname]);

  const contextValues = useMemo(
    () => ({
      disputeData,
      setDisputeData,
      disputeTemplate,
      resetDisputeData,
      isSubmittingCase,
      setIsSubmittingCase,
      isPolicyUploading,
      setIsPolicyUploading,
      isBatchCreation,
      setIsBatchCreation,
      batchSize,
      setBatchSize,
      selectedFeatures,
      setSelectedFeatures,
    }),
    [
      disputeData,
      disputeTemplate,
      resetDisputeData,
      isSubmittingCase,
      isPolicyUploading,
      setDisputeData,
      isBatchCreation,
      setIsBatchCreation,
      batchSize,
      setBatchSize,
      selectedFeatures,
      setSelectedFeatures,
    ]
  );

  return <NewDisputeContext.Provider value={contextValues}>{children}</NewDisputeContext.Provider>;
};

const constructDisputeTemplate = (disputeData: IDisputeData) => {
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const { courtId, numberOfJurors, arbitrationCost, disputeKitId, ...baseTemplate } = disputeData;

  if (!isUndefined(baseTemplate.aliasesArray)) {
    baseTemplate.aliasesArray = baseTemplate.aliasesArray.filter((item) => item.address !== "" && item.isValid);
    if (baseTemplate.aliasesArray.length === 0) delete baseTemplate.aliasesArray;
    else {
      const aliases: Alias = {};

      for (const alias of baseTemplate.aliasesArray) {
        aliases[alias.name] = alias.address;
      }

      baseTemplate.aliases = aliases;
    }
  }

  for (const answer of baseTemplate.answers) {
    answer.id = "0x" + BigInt(answer.id).toString(16);
  }
  if (!isUndefined(baseTemplate.policyURI) && isEmpty(baseTemplate.policyURI)) delete baseTemplate.policyURI;

  baseTemplate.arbitratorAddress = klerosCoreAddress[DEFAULT_CHAIN.id];
  baseTemplate.arbitratorChainID = DEFAULT_CHAIN.id.toString();

  return baseTemplate as IDisputeTemplate;
};
