import { Address, Hex, isAddress } from "viem";
import { privateKeyToAddress } from "viem/accounts";

import { configureSDK } from "@kleros/kleros-sdk/src/sdk";

import { ALL_CHAINS, DEFAULT_CHAIN } from "consts/chains";

