import { UnsupportedActionError } from "../errors";
import { callAction } from "./actions/callAction";
import { eventAction } from "./actions/eventAction";
import { fetchIpfsJsonAction } from "./actions/fetchIpfsJsonAction";
import { jsonAction } from "./actions/jsonAction";
import { subgraphAction } from "./actions/subgraphAction";
import { retrieveRealityData } from "./retrieveRealityData";
import {
  validateAbiCallMapping,
  validateAbiEventMapping,
  validateFetchIpfsJsonMapping,
  validateJsonMapping,
  validateRealityMapping,
  validateSubgraphMapping,
} from "./utils/actionTypeValidators";
import { ActionMapping } from "./utils/actionTypes";
import { replacePlaceholdersWithValues } from "./utils/replacePlaceholdersWithValues";
import { Address } from "viem";

// Add these type definitions at the top of the file
type ActionResult = Record<string, unknown> | null | undefined;

// Update the function signature
export const executeAction = async (
  mapping: ActionMapping,
  context: Record<string, unknown> = {}
): Promise<ActionResult> => {
  mapping = replacePlaceholdersWithValues(mapping, context) as ActionMapping;

  switch (mapping.type) {
    case "graphql":
      return await subgraphAction(validateSubgraphMapping(mapping));
    case "json":
      return jsonAction(validateJsonMapping(mapping));
    case "abi/call":
      return await callAction(validateAbiCallMapping(mapping));
    case "abi/event":
      return await eventAction(validateAbiEventMapping(mapping));
    case "fetch/ipfs/json":
      return await fetchIpfsJsonAction(validateFetchIpfsJsonMapping(mapping));
    case "reality":
      mapping = validateRealityMapping(mapping);
      return await retrieveRealityData(mapping.realityQuestionID, context.arbitrableAddress as Address);
    default:
      throw new UnsupportedActionError(`Unsupported action type: ${JSON.stringify(mapping)}`);
  }
};

export const executeActions = async (
  mappings: ActionMapping[],
  initialContext: Record<string, unknown> = {}
): Promise<Record<string, unknown>> => {
  const context: Record<string, unknown> = { ...initialContext };

  for (const mapping of mappings) {
    const actionResult = await executeAction(mapping, context);

    if (actionResult) {
      Object.keys(actionResult).forEach((key) => {
        context[key] = actionResult[key];
      });
    }
  }

  return context;
};
import mustache from "mustache";
import { DisputeDetails } from "./disputeDetailsTypes";
import DisputeDetailsSchema, { RefuseToArbitrateAnswer } from "./disputeDetailsSchema";
import { lambdas } from "./lambdas";

export const populateTemplate = (mustacheTemplate: string, data: Record<string, unknown>): DisputeDetails => {
  const render = mustache.render(mustacheTemplate, { ...lambdas, ...data });
  const dispute = JSON.parse(render);

  const validation = DisputeDetailsSchema.safeParse(dispute);
  if (!validation.success) {
    throw validation.error;
  }

  return findAndUpdateRTA(dispute);
};

// Filter out any existing answer with id 0 and add customised Refuse to Arbitrate option
const findAndUpdateRTA = (dispute: DisputeDetails) => {
  const templateRTAIndex = (dispute as DisputeDetails).answers.findIndex(
    (answer) => answer.id && BigInt(answer.id) === BigInt(0)
  );

  if (templateRTAIndex !== -1) {
    dispute.answers[templateRTAIndex] = {
      ...RefuseToArbitrateAnswer,
      description: dispute.answers[templateRTAIndex].description ?? RefuseToArbitrateAnswer.description,
    };
  } else {
    dispute.answers = [RefuseToArbitrateAnswer, ...dispute.answers];
  }

  return dispute;
};
import mustache from "mustache";
import retrieveVariables from "./retrieveVariables";
import { ActionMapping } from "./actionTypes";
import { InvalidContextError } from "../../errors";
import { isUndefined } from ".";

export function replacePlaceholdersWithValues(
  mapping: ActionMapping,
  context: Record<string, unknown>
): ActionMapping | ActionMapping[] {
  function replace(obj: ActionMapping): ActionMapping | ActionMapping[] {
    if (typeof obj === "string") {
      validateContext(obj, context);
      return mustache.render(obj, context) as unknown as ActionMapping;
    } else if (Array.isArray(obj)) {
      return obj.map(replace) as unknown as ActionMapping[];
    } else if (typeof obj === "object" && obj !== null) {
      return Object.fromEntries(
        Object.entries(obj).map(([key, value]) => [key, replace(value)])
      ) as unknown as ActionMapping[];
    } else {
      return obj;
    }
  }

  return replace(mapping);
}

/**
 *
 * @param template
 * @param context
 * @description retrieves all variables from a template and validates if they are provided in the context
 */
const validateContext = (template: string, context: Record<string, unknown>) => {
  const variables = retrieveVariables(template);

  variables.forEach((variable) => {
    if (isUndefined(context[variable]))
      throw new InvalidContextError(`Expected key "${variable}" to be provided in context.`);
  });
  return true;
};
import { MAX_BYTE_SIZE } from "../../consts";
import { RequestError } from "../../errors";
import { FetchIpfsJsonMapping } from "../utils/actionTypes";
import { createResultObject } from "../utils/createResultObject";

export const fetchIpfsJsonAction = async (mapping: FetchIpfsJsonMapping) => {
  const { ipfsUri, seek, populate } = mapping;

  let httpUri;
  if (ipfsUri.startsWith("/ipfs/")) {
    httpUri = `https://ipfs.io${ipfsUri}`;
  } else if (ipfsUri.startsWith("ipfs://")) {
    httpUri = ipfsUri.replace("ipfs://", "https://ipfs.io/ipfs/");
  } else if (!ipfsUri.startsWith("http")) {
    httpUri = `https://ipfs.io/ipfs/${ipfsUri}`;
  } else {
    throw new RequestError("Invalid IPFS URI format", httpUri);
  }

  const response = await fetch(httpUri, { method: "GET" });

  if (!response.ok) {
    throw new RequestError("Failed to fetch data from IPFS", httpUri);
  }

  const contentLength = response.headers.get("content-length");
  if (contentLength && parseInt(contentLength) > MAX_BYTE_SIZE) {
    throw new RequestError("Response size is too large", httpUri);
  }

  const contentType = response.headers.get("content-type");
  if (!contentType || !contentType.includes("application/json")) {
    throw new RequestError("Fetched data is not JSON", httpUri);
  }

  const data = await response.json();

  return createResultObject(data, seek, populate);
};
