export const userFragment = graphql(`
  fragment UserDetails on User {
    totalDisputes
    totalResolvedDisputes
    totalAppealingDisputes
    totalCoherentVotes
    totalResolvedVotes
    coherenceScore
    tokens {
      court {
        id
        name
      }
    }
    shifts {
      pnkAmount
      ethAmount
    }
  }
`);

const userQuery = graphql(`
  query User($address: ID!) {
    user(id: $address) {
      disputes(orderBy: lastPeriodChange) {
        id
      }
      ...UserDetails
    }
  }
`);

const userQueryDisputeFilter = graphql(`
  query UserDisputeFilter($address: ID!, $where: Dispute_filter) {
    user(id: $address) {
      disputes(orderBy: lastPeriodChange, where: $where) {
        id
      }
      ...UserDetails
    }
  }
`);

export const useUserQuery = (address?: Address, where?: Dispute_Filter) => {
  query JurorsByCoherenceScore(
    $skip: Int
    $first: Int
    $orderBy: User_orderBy
    $orderDirection: OrderDirection
    $search: String
  ) {
    users(
      first: $first
      skip: $skip
      orderBy: $orderBy
      orderDirection: $orderDirection
      where: { totalResolvedVotes_gt: 0, userAddress_contains: $search }
    ) {
      id
      coherenceScore
      totalCoherentVotes
      totalResolvedVotes
      totalResolvedDisputes
    }
  }
`);

export const useJurorsByCoherenceScore = (
  skip = 0,
  first = 20,
  orderBy: string,
  orderDirection: string,
  query TopStakedJurorsByCourt(
    $courtId: ID!
    $skip: Int
    $first: Int
    $orderBy: JurorTokensPerCourt_orderBy
    $orderDirection: OrderDirection
    $search: String
  ) {
    jurorTokensPerCourts(
      where: { court_: { id: $courtId }, effectiveStake_gt: 0, juror_: { userAddress_contains_nocase: $search } }
      skip: $skip
      first: $first
      orderBy: $orderBy
      orderDirection: $orderDirection
    ) {
      court {
        id
      }
      juror {
        id
        userAddress
      }
      effectiveStake
    }
  }
`);

  query HomePageBlock($pastTimestamp: BigInt) {
    presentCourts: courts(orderBy: id, orderDirection: asc, first: 1000) {
      id
      parent {
        id
      }
      name
      numberDisputes
      numberVotes
      feeForJuror
      effectiveStake
    }
    pastCourts: courtCounters(
